import React from 'react';
import styles from './Projects.module.css';

const Projects = () => {
  const projects = [
    {
      name: 'TestFlow Automation Framework',
      description: 'Python + Selenium + pytest framework for regression testing of e-commerce workflows. Reduced manual testing time by 60% with parallel execution.',
      tech: ['Python', 'Selenium', 'pytest', 'GitHub Actions'],
      repo: 'github.com/safayetsawom/testflow'
    },
    {
      name: 'ScrapeSense',
      description: 'Web scraper that extracts product data from multiple e-commerce sources, deduplicates entries, and exports structured CSV reports with data validation.',
      tech: ['Python', 'Scrapy', 'pandas', 'BeautifulSoup'],
      repo: 'github.com/safayetsawom/scrapesense'
    },
    {
      name: 'API Sentinel',
      description: 'Automated API testing suite using Postman Collections and Newman CLI. Validates REST endpoints, checks response schemas, and generates HTML reports.',
      tech: ['Postman', 'Newman', 'JavaScript', 'REST APIs'],
      repo: 'github.com/safayetsawom/api-sentinel'
    }
  ];

  return (
    <section className={styles.section} id="projects">
      <div className={styles.container}>
        <h2 className={styles.sectionTitle}>
          <span className={styles.prompt}>$</span> ls -la ~/projects/
        </h2>
        
        <div className={styles.projectsList}>
          {projects.map((project, index) => (
            <div key={index} className={styles.projectCard}>
              <div className={styles.projectIndex}>
                [{String(index).padStart(2, '0')}]
              </div>
              
              <div className={styles.projectContent}>
                <h3 className={styles.projectName}>
                  <span className={styles.prompt}>$</span> {project.name}
                </h3>
                
                <p className={styles.projectDesc}>{project.description}</p>
                
                <div className={styles.techStack}>
                  {project.tech.map((tech, idx) => (
                    <span key={idx} className={styles.techChip}>{tech}</span>
                  ))}
                </div>
                
                <div className={styles.projectFooter}>
                  <span className={styles.repoLink}>
                    <span className={styles.prompt}>▶</span> {project.repo}
                  </span>
                </div>
              </div>
            </div>
          ))}
        </div>
        
        <div className={styles.note}>
          <span className={styles.prompt}>$</span> 
          <span className={styles.noteText}>more projects available on GitHub</span>
          <a 
            href="https://github.com/safayetsawom" 
            target="_blank" 
            rel="noopener noreferrer"
            className={styles.link}
          >
            github.com/safayetsawom
          </a>
        </div>
      </div>
    </section>
  );
};

export default Projects;
